const body = $json.body || $json || {};
const headers = $json.headers || {};
const clean = (v) => String(v ?? '').trim();
const isUuid = (v) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(clean(v));

const authorization = clean(headers.authorization || headers.Authorization);
if (!authorization.startsWith('Bearer ') || authorization.length <= 7) {
  throw new Error('Worker RC1 requiere Authorization Bearer.');
}

const request_id = clean(body.request_id);
const usuario_id = clean(body.usuario_id);
const conversacion_id = clean(body.conversacion_id);
if (!isUuid(request_id) || !isUuid(usuario_id) || !isUuid(conversacion_id)) {
  throw new Error('Worker RC1 recibió identidad inválida.');
}

const accionObj = body.accion && typeof body.accion === 'object' && !Array.isArray(body.accion)
  ? body.accion
  : {};
const accion = clean(accionObj.tipo).toUpperCase();
const allowed = new Set([
  'CREAR_TAREA',
  'CREAR_OBJETIVO',
  'GUARDAR_MEMORIA',

  /*
    Las tres del negocio. Estaban listas en todos lados menos acá.

    El modelo las sabia pedir, el prompt se las ensenaba, el gateway tenia su
    ruta, la tabla de riesgo del gate les daba tier 3, los constraints de la
    base las admitian desde la v83 y el ejecutor existia desde la v84. Pero
    esta lista no las incluia, asi que el worker las rechazaba antes de
    llegar a pedir autorizacion.

    Efecto visible: el chat mostraba 'Operacion lista para registrar' y la
    pantalla de aprobaciones quedaba vacia. Una clienta lo reporto el 31 de
    agosto de 2026; el gate no habia visto un REGISTRAR_VENTA en su vida.
  */
  'REGISTRAR_VENTA',
  'AJUSTAR_STOCK',
  'CREAR_CONTACTO',

  /*
    Cargar productos al catálogo (v131). Cuarta acción del negocio, y cuarto
    lugar donde hay que darla de alta: cuando faltó SOLO acá, el gateway
    recibía un {} sin error y desde el chat parecía que se había ejecutado.
  */
  'CREAR_PRODUCTO',

  /*
    Poner el costo y corregir el precio de lo que ya existe. Quinta acción del
    negocio, cuarta vez que se pasa por esta lista, y la tercera vez que hay
    que acordarse de que existe.
  */
  'ACTUALIZAR_PRODUCTO',

  /*
    La plata que sale y la que se va a repetir. Sexta y séptima acción del
    negocio, y cuarta vez que hay que acordarse de esta lista.
  */
  'REGISTRAR_COMPRA',
  'REGISTRAR_GASTO_FIJO',

  /*
    La plata de la persona, que desde la v136 vive separada de la del negocio.
  */
  'REGISTRAR_MOVIMIENTO_PERSONAL',

  /*
    Plata movida entre cuentas propias. No es gasto ni ingreso: por eso tiene
    acción propia y tabla propia.
  */
  'REGISTRAR_TRANSFERENCIA',

  /*
    Las deudas. Declarar una es barato a propósito: a alguien endeudado hay que
    ponerle la menor cantidad de trabas para contarle a EOS cuánto debe.
  */
  'REGISTRAR_DEUDA',
  'REGISTRAR_PAGO_DEUDA',

  /*
    Corregir lo que quedó mal anotado. Cuesta 1 punto, menos que anotarlo: casi
    siempre existe porque EOS entendió mal un monto, y cobrarle a la persona el
    mismo presupuesto por el error del sistema que por su propio trabajo la
    deja sin cupo justo cuando está arreglando algo que no rompió ella.
  */
  'CORREGIR_MOVIMIENTO',

  /*
    Anotar cuánta plata hay en una cuenta. Cuesta 1 punto, el mínimo: es el
    dato del que dependen el patrimonio, el disponible real y la cobertura del
    fondo de emergencia, y el que más cambia. Cobrarle presupuesto de riesgo a
    la persona por contarle a EOS cuánto tiene la enseñaría a no contárselo.
  */
  'DECLARAR_SALDO',

  /*
    Cobrar una venta y pagar una compra: 4 puntos, como pagar una cuota. Son
    las dos acciones del negocio que escriben en DOS lados a la vez —bajan el
    saldo del documento y dejan el movimiento financiero— y un cobro mal
    cargado deja una factura como cobrada, que la persona deja de reclamar.
  */
  'REGISTRAR_COBRO',
  'REGISTRAR_PAGO_COMPRA',

  /*
    Las tarjetas. Cargar la tarjeta cuesta 1, como declarar un saldo: es la
    persona contándole a EOS un hecho sobre su plata, y el resumen cambia todos
    los meses. La compra en cuotas cuesta 2, porque crea hasta doce
    vencimientos futuros y una duplicada infla el calendario del mes.
  */
  'REGISTRAR_TARJETA',
  'REGISTRAR_COMPRA_TARJETA'
]);
if (!allowed.has(accion)) {
  throw new Error(`Acción no permitida en este endpoint: ${accion || 'vacía'}`);
}

const datos = accionObj.datos && typeof accionObj.datos === 'object' && !Array.isArray(accionObj.datos)
  ? accionObj.datos
  : {};

const payload = {
  mensaje: clean(body.mensaje),
  datos,
  metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
    ? body.metadata
    : {}
};

const authorize_body = {
  usuario_id,
  request_id,
  accion,
  payload,
  conversacion_id,
  origen: 'n8n-worker-gated-rc1'
};

return [{
  json: {
    request_id,
    usuario_id,
    conversacion_id,
    nombre: clean(body.nombre || 'Usuario'),
    mensaje: clean(body.mensaje),
    respuesta_gateway: clean(body.respuesta_gateway),
    accion,
    accion_datos: datos,
    plan: clean(body.plan || 'free'),
    origen: clean(body.origen || 'eos-web'),
    metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata) ? body.metadata : {},
    authorization,
    authorize_body,
    received_at: clean(body.received_at || new Date().toISOString())
  }
}];

const src = $('01 INT Preparar').first().json || {};
const auth = $input.first().json || {};
const isUuid = (v) => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v || ''));

const execute = auth.ok === true && auth.execute === true && isUuid(auth.command_id);
const base = 'https://www.transtech.com.py'.replace(/\/$/, '');

return [{
  json: {
    ...src,
    auth,
    execute,
    command_id: isUuid(auth.command_id) ? auth.command_id : null,
    target_url: execute
      ? `${base}/api/internal/action-effects/v1`
      : `${base}/api/internal/worker-authorize/v1`,
    target_body: execute
      ? { command_id: auth.command_id }
      : src.authorize_body
  }
}];

/*
  Guaraníes como los escribe alguien de acá: punto para los miles, coma para
  los decimales, y sin decimales cuando no los hay.

  Los costos que salen de una cuenta con envío llegan con medio guaraní
  (122.414,5) y redondearlos en la confirmación mostraría un número distinto
  del que quedó guardado.
*/
function plata(n) {
  const x = Number(n);
  if (!isFinite(x)) return String(n);

  const negativo = x < 0;
  const abs = Math.abs(x);
  const entero = Math.floor(abs);

  let texto = String(entero).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

  const decimal = Math.round((abs - entero) * 100);
  if (decimal > 0) {
    let d = String(decimal);
    if (d.length === 1) d = '0' + d;
    if (d.charAt(1) === '0') d = d.charAt(0);
    texto = texto + ',' + d;
  }

  return (negativo ? '-' : '') + texto;
}

/*
  Qué cambió, campo por campo, con el antes y el después.

  "Actualicé el producto" no sirve: cambiar un precio de 165.000 a 200.000 y
  decir "listo" deja a la persona sin saber si el sistema entendió 200.000 o
  20.000, que es exactamente el error que hay que poder ver enseguida. La
  v133 devuelve el antes justamente para poder escribirlo.
*/
function fraseDeCambios(result) {
  const r = (result && result.resultado) || {};
  const hechos = Array.isArray(r.actualizados) ? r.actualizados : [];
  const faltan = Array.isArray(r.no_encontrados) ? r.no_encontrados : [];
  const iguales = Array.isArray(r.sin_cambios) ? r.sin_cambios : [];

  const etiqueta = { precio_venta: 'precio', costo: 'costo', iva: 'IVA' };

  const partes = [];

  for (const p of hechos) {
    const cambios = p.cambios || {};
    const trozos = [];

    for (const campo of ['precio_venta', 'costo', 'iva']) {
      const c = cambios[campo];
      if (!c) continue;

      const antes = c.antes === null || c.antes === undefined;
      const valor = campo === 'iva' ? c.despues + '%' : plata(c.despues);

      trozos.push(
        antes
          ? etiqueta[campo] + ' ' + valor + ' (no tenía)'
          : etiqueta[campo] + ' de ' + (campo === 'iva' ? c.antes + '%' : plata(c.antes)) + ' a ' + valor
      );
    }

    if (trozos.length) partes.push('\u201C' + p.nombre + '\u201D: ' + trozos.join(', '));
  }

  const frases = [];

  if (partes.length === 1) frases.push('Actualicé ' + partes[0] + '.');
  else if (partes.length > 1) frases.push('Actualicé ' + partes.length + ' productos. ' + partes.join('. ') + '.');

  // Acá y no al final: después del aviso de que un producto no estaba, "lo
  // ves en Negocio > Productos" se lee como si hablara de ese.
  if (partes.length) frases.push('Lo ves en Negocio > Productos.');

  if (iguales.length === 1) frases.push('\u201C' + iguales[0] + '\u201D ya estaba así.');
  else if (iguales.length > 1) frases.push(iguales.length + ' ya estaban así.');

  if (faltan.length) {
    frases.push(
      (faltan.length === 1 ? 'No encontré \u201C' + faltan[0] + '\u201D' : 'No encontré ' + faltan.length + ' de los que nombraste') +
      ' en tu catálogo: pasame el precio de venta y te lo cargo.'
    );
  }

  if (!frases.length) return 'No quedó nada para actualizar.';

  return frases.join(' ');
}

/*
  La frase la arma la acción que sabe qué pasó; las que no tienen nada que
  contar además de que se hicieron caen en `doneText`.
*/
/*
  La compra dice el TOTAL, que es lo único verificable de un vistazo contra lo
  que la persona dictó, y dice qué conceptos NO están en el catálogo, porque
  de eso depende si movió stock o solamente plata.
*/
function fraseDeCompra(result) {
  const r = (result && result.resultado) || {};
  const items = Array.isArray(r.compra) ? r.compra : [];
  const fuera = Array.isArray(r.sin_catalogo) ? r.sin_catalogo : [];
  const total = r.total_compra;

  if (!items.length) return 'No quedó ningún concepto para registrar.';

  const frases = [];

  frases.push(
    items.length === 1
      ? 'Registré la compra de ' + items[0].concepto + ' por \u20B2 ' + plata(total) + '.'
      : 'Registré una compra de ' + items.length + ' conceptos por \u20B2 ' + plata(total) + ' en total.'
  );

  frases.push('La ves en Negocio > Compras, y el gasto ya está en el panel financiero.');

  /*
    Tres estados distintos, y la diferencia importa:

      · en el catálogo y con inventario  -> subió el stock y el costo
      · en el catálogo sin inventario    -> SOLO el costo
      · fuera del catálogo               -> ni una cosa ni la otra

    El del medio decía lo mismo que el primero, y hacía creer que el sistema
    estaba contando existencias que nadie contaba.
  */
  const conStock = items.filter(function (x) { return x.mueve_stock; });
  const soloCosto = items.filter(function (x) { return x.en_catalogo && !x.mueve_stock; });

  if (conStock.length) {
    frases.push(
      conStock.length === 1
        ? 'A \u201C' + conStock[0].concepto + '\u201D le sumé el stock y le actualicé el costo.'
        : 'A ' + conStock.length + ' de ellos les sumé stock y les actualicé el costo.'
    );
  }

  if (soloCosto.length) {
    frases.push(
      (soloCosto.length === 1
        ? 'A \u201C' + soloCosto[0].concepto + '\u201D le actualicé el costo'
        : 'A ' + soloCosto.length + ' de ellos les actualicé el costo') +
      ', pero no llevan inventario, así que el stock no se movió. Se activa en Negocio > Productos.'
    );
  }

  if (fuera.length) {
    frases.push(
      (fuera.length === 1
        ? '\u201C' + fuera[0] + '\u201D no está en tu catálogo'
        : fuera.length + ' de esos conceptos no están en tu catálogo') +
      ', así que quedaron como gasto y no mueven inventario. Si querés que lleven stock, pasame su precio de venta y los cargo.'
    );
  }

  if (r.proveedor && !r.proveedor.agendado) {
    frases.push('No encontré a \u201C' + r.proveedor.nombre + '\u201D en tus contactos, así que la compra quedó sin proveedor.');
  }

  return frases.join(' ');
}

/*
  El fijo dice la CONVERSIÓN. "750.000 cada 15 días" se guarda como 1.500.000
  por mes y ese número sale después en el pronóstico de caja: sin explicar de
  dónde salió, la única lectura posible es que el sistema se equivocó al doble.
*/
function fraseDeFijos(result) {
  const r = (result && result.resultado) || {};
  const fijos = Array.isArray(r.fijos) ? r.fijos : [];

  if (!fijos.length) return 'No quedó ningún gasto fijo declarado.';

  const partes = fijos.map(function (f) {
    const donde = f.ambito === 'negocio' ? ' (del negocio)' : '';
    const base = f.descripcion + donde + ': \u20B2 ' + plata(f.monto_mensual) + ' por mes';
    return f.convertido
      ? base + ' (\u20B2 ' + plata(f.monto_original) + ' ' + f.frecuencia + ')'
      : base;
  });

  /*
    Dónde se corrige, que no es el mismo lugar para los dos.

    Los del negocio viven en Negocio > Resultado y los de la persona en
    Personal. Mandar a alguien a la sección equivocada a buscar algo que ahí no
    está es tan malo como no decir nada: se busca, no se encuentra, y lo que
    queda es que el sistema no lo guardó.
  */
  const soloNegocio = fijos.every(function (f) { return f.ambito === 'negocio'; });
  const soloPersonal = fijos.every(function (f) { return f.ambito !== 'negocio'; });
  const donde = soloNegocio
    ? 'Negocio > Resultado'
    : soloPersonal
      ? 'Personal'
      : 'la sección de cada uno';

  const dias = fijos.map(function (f) { return f.dia_del_mes; });
  const mismoDia = dias.every(function (d) { return d === dias[0]; });

  return (
    (fijos.length === 1 ? 'Anoté ' : 'Anoté ' + fijos.length + ' fijos: ') +
    partes.join('; ') + '. ' +
    'Lo cuento ' + (mismoDia ? 'el día ' + dias[0] : 'en el día que registré cada uno') +
    ' de cada mes; si es otro, cambialo en ' + donde + '.'
  );
}

/*
  Dice DÓNDE quedó, no solo cuánto.

  Desde la v136 hay dos lugares posibles y son incompatibles: Negocios y
  Personal. Si EOS entendió mal de cuál era, la confirmación es la única
  oportunidad de que el usuario lo vea en el momento — después habría que
  encontrarlo revisando un panel que no cuadra.
*/
function fraseDePersonal(result) {
  const r = (result && result.resultado) || {};
  const ms = Array.isArray(r.movimientos) ? r.movimientos : [];

  if (!ms.length) return 'No quedó nada anotado.';

  const partes = ms.map(function (m) {
    /*
      Tres verbos, no dos. Una devolución dice "Volvió": decir "Entró" la
      confundiría con un ingreso, que es exactamente la distinción que la
      v141 vino a marcar, y decir "Salió" sería al revés.
    */
    const signo = m.tipo === 'ingreso'
      ? 'Entró'
      : (m.tipo === 'devolucion' ? 'Volvió' : 'Salió');
    return signo + ' \u20B2 ' + plata(m.monto) + ' \u2014 ' + m.descripcion;
  });

  const cierre = ms.length === 1
    ? 'Lo anoté en Personal.'
    : 'Los anoté en Personal.';

  return partes.join('. ') + '. ' + cierre + ' No toca las cuentas del negocio.';
}

function fraseDeAccion(accion, result) {
  if (accion === 'CREAR_PRODUCTO') return fraseDeProductos(result);
  if (accion === 'ACTUALIZAR_PRODUCTO') return fraseDeCambios(result);
  if (accion === 'REGISTRAR_COMPRA') return fraseDeCompra(result);
  if (accion === 'REGISTRAR_GASTO_FIJO') return fraseDeFijos(result);
  if (accion === 'REGISTRAR_MOVIMIENTO_PERSONAL') return fraseDePersonal(result);
  if (accion === 'REGISTRAR_TRANSFERENCIA') return fraseDeTransferencia(result);
  if (accion === 'REGISTRAR_DEUDA') return fraseDeDeuda(result);
  if (accion === 'REGISTRAR_PAGO_DEUDA') return fraseDePagoDeuda(result);
  if (accion === 'CORREGIR_MOVIMIENTO') return fraseDeCorreccion(result);
  if (accion === 'DECLARAR_SALDO') return fraseDeSaldo(result);
  if (accion === 'REGISTRAR_COBRO' || accion === 'REGISTRAR_PAGO_COMPRA') {
    return fraseDeCartera(result);
  }
  if (accion === 'REGISTRAR_TARJETA') return fraseDeTarjeta(result);
  if (accion === 'REGISTRAR_COMPRA_TARJETA') return fraseDeCompraTarjeta(result);
  return null;
}

function fraseDeTarjeta(result) {
  const r = (result && result.resultado) || {};
  if (!r.tarjeta) return null;

  const signo = signoDe(r.moneda);
  const frases = [];

  if (r.creada) {
    frases.push('Cargué ' + r.tarjeta + '.');
  }

  /*
    El resumen manda sobre el resto: si la persona acaba de contar cuánto vino,
    lo que quiere ver confirmado es ese número y cuándo hay que pagarlo.
  */
  if (r.pago_total !== null && r.pago_total !== undefined) {
    var linea = 'Resumen: ' + signo + plata(r.pago_total);
    if (r.pago_minimo !== null && r.pago_minimo !== undefined) {
      linea += ', mínimo ' + signo + plata(r.pago_minimo);
    }
    if (r.dia_vencimiento) linea += '. Vence el ' + r.dia_vencimiento;
    frases.push(linea + '.');
  } else if (!r.creada) {
    frases.push('Actualicé ' + r.tarjeta + '.');
  }

  if (r.dia_cierre && r.dia_vencimiento && r.creada) {
    frases.push('Cierra el ' + r.dia_cierre + ' y vence el ' + r.dia_vencimiento + '.');
  }

  /*
    Sin el ciclo no se puede calcular NADA de esta tarjeta: ni cuándo cae la
    cuota, ni si entra en el mes. Decirlo acá cuesta una línea; que la persona
    lo descubra mirando un panel vacío cuesta la confianza.
  */
  if (r.falta_ciclo) {
    frases.push('Me falta qué día cierra y qué día vence para poder calcularte los vencimientos.');
  }

  return frases.join(' ');
}

function fraseDeCompraTarjeta(result) {
  const r = (result && result.resultado) || {};
  if (!r.descripcion) return null;

  const signo = signoDe(r.moneda);
  const cuotas = Number(r.cuotas) || 1;
  const frases = [];

  frases.push(
    cuotas > 1
      ? 'Anoté ' + r.descripcion + ': ' + cuotas + ' cuotas de ' + signo + plata(r.monto_cuota) +
        ' en ' + r.tarjeta + '.'
      : 'Anoté ' + r.descripcion + ' por ' + signo + plata(r.monto_cuota) + ' en ' + r.tarjeta + '.'
  );

  if (r.cuota_estimada) {
    frases.push(
      'La cuota la saqué del total dividido ' + cuotas +
      '; si con los intereses es otra, decímela.'
    );
  }

  /*
    Lo contraintuitivo, dicho en voz alta. La persona acaba de gastar y va a
    buscar la compra en su panel del mes: si no la encuentra y nadie le
    explicó por qué, concluye que no se anotó.
  */
  frases.push('No es un gasto de este mes: sale cuando pagues el resumen.');

  return frases.join(' ');
}

/*
  La frase dice A QUIÉN, CUÁNTO, CONTRA QUÉ y CUÁNTO QUEDA.

  Lo que queda es lo que más importa. Un cobro parcial anunciado como "listo"
  hace creer que la cuenta quedó saldada, y una factura que se cree cobrada es
  una factura que nadie vuelve a reclamar. Por eso el resto va siempre, aunque
  sea cero — decir "no te debe más nada" es tan útil como decir cuánto falta.
*/
function diaMes(iso) {
  if (!iso || iso.length < 10) return String(iso || '');
  return iso.slice(8, 10) + '/' + iso.slice(5, 7);
}

function fraseDeCartera(result) {
  const r = (result && result.resultado) || {};
  if (!r.contacto) return null;

  const signo = signoDe(r.moneda);
  const docs = Array.isArray(r.documentos) ? r.documentos : [];
  const cerrados = Number(r.cerrados) || 0;
  const resta = Number(r.resta) || 0;

  const frases = [
    (r.es_venta ? 'Cobré ' : 'Pagué ') + signo + plata(r.aplicado) + ' a ' + r.contacto + '.'
  ];

  if (docs.length === 1) {
    frases.push(
      cerrados === 1
        ? 'Saldó la factura del ' + diaMes(docs[0].fecha) + '.'
        : 'Va a cuenta de la del ' + diaMes(docs[0].fecha) + '.'
    );
  } else if (docs.length > 1) {
    /*
      Cuando cierra UNA sola, se dice cuál en vez de decir "1".
      "Saldó la del 21/08" ubica a la persona; "Cerró 1 facturas" además de
      estar mal escrito no le dice nada que no supiera.
    */
    var cerradas = docs.filter(function (d) { return d.saldaba; });

    var parte = cerrados === 1
      ? 'Saldó la del ' + diaMes(cerradas[0].fecha)
      : 'Cerró ' + cerrados + ' facturas';

    if (cerrados === 0) {
      parte = 'Repartido entre ' + docs.length + ' facturas';
    }

    frases.push(
      cerrados > 0 && cerrados < docs.length
        ? parte + ' y el resto quedó a cuenta de la del ' + diaMes(docs[docs.length - 1].fecha) + '.'
        : parte + '.'
    );
  }

  frases.push(
    resta > 0
      ? (r.es_venta ? 'Le quedan ' : 'Te quedan ') + signo + plata(resta) + '.'
      : (r.es_venta ? 'No te debe más nada.' : 'No le debés más nada.')
  );

  return frases.join(' ');
}

/*
  La frase dice EN QUÉ CUENTA, CUÁNTO y CUÁNTO HABÍA.

  El antes es lo que permite ver que EOS escribió en la cuenta equivocada:
  'Ueno pasó de 1.200.000 a 3.000.000' sobre una cuenta que la persona sabe
  que tenía otra cosa se nota en el acto. Sin él, un saldo en el lugar
  equivocado deja mal el patrimonio, el disponible y la cobertura a la vez, y
  los dos números quedan plausibles.

  La moneda va siempre: '3.000.000' sobre una cuenta en dólares es mil veces
  el patrimonio real.

  Y si la cuenta quedó sin clasificar, se dice. Es lo que se evitó suponer, y
  ofrecerlo en una línea cuesta menos que una pantalla.
*/
function signoDe(moneda) {
  if (moneda === 'USD') return 'US$ ';
  if (!moneda || moneda === 'PYG') return '₲ ';
  return moneda + ' ';
}

function fraseDeSaldo(result) {
  const r = (result && result.resultado) || {};
  if (!r.cuenta) return null;

  const signo = signoDe(r.moneda);
  const cuanto = signo + plata(r.saldo);
  const frases = [];

  if (r.creada) {
    frases.push('Anoté ' + cuanto + ' en ' + r.cuenta + '. Cuenta nueva.');
    if (r.sin_clasificar) {
      frases.push('Quedó sin clasificar: decime si es banco, cooperativa, financiera o billetera.');
    }
  } else if (r.antes === null || r.antes === undefined) {
    frases.push('Anoté ' + cuanto + ' en ' + r.cuenta + '.');
  } else if (Number(r.antes) === Number(r.saldo)) {
    frases.push(r.cuenta + ' sigue en ' + cuanto + '.');
  } else {
    frases.push(r.cuenta + ' pasó de ' + signo + plata(r.antes) + ' a ' + cuanto + '.');
  }

  return frases.join(' ');
}

/*
  La frase dice QUÉ movimiento tocó y qué tenía antes.

  Es lo único que le permite a la persona darse cuenta de que EOS corrigió el
  equivocado: 'nafta' coincide con varias filas y se toma la más reciente. Sin
  el antes y el cuál, 'listo' sobre la fila equivocada pasa desapercibido.
*/
function fraseDeCorreccion(result) {
  const r = (result && result.resultado) || {};
  const antes = r.antes || {};
  const despues = r.despues || {};

  if (!antes.descripcion && !despues.descripcion) return 'No encontré ese movimiento.';

  const frases = [];
  const que = despues.descripcion || antes.descripcion;

  if (antes.monto !== despues.monto) {
    frases.push('Corregí ' + que + ' del ' + antes.fecha + ': de ₲ ' + plata(antes.monto) +
      ' a ₲ ' + plata(despues.monto) + '.');
  } else if (antes.fecha !== despues.fecha) {
    frases.push('Moví ' + que + ' del ' + antes.fecha + ' al ' + despues.fecha + '.');
  } else {
    frases.push('Corregí el movimiento del ' + antes.fecha + ': ahora dice ' + que + '.');
  }

  if (Number(r.coincidencias) > 1) {
    frases.push('Coincidían ' + r.coincidencias + ' y tomé el más reciente; si era otro, decímelo.');
  }

  return frases.join(' ');
}

/*
  Al declarar una deuda, lo importante es que se vea el número que se guardó y
  qué le falta a EOS para poder ayudar. Una deuda sin cuota no entra en el plan
  de pago: se puede ver, pero no se puede ordenar.
*/
function fraseDeDeuda(result) {
  const r = (result && result.resultado) || {};
  if (!r.acreedor) return 'No quedó registrada la deuda.';

  const cambios = r.cambios || {};
  const frases = [];

  if (r.creada) {
    frases.push('Anoté que le debés \u20B2 ' + plata(r.saldo) + ' a ' + r.acreedor + '.');
  } else if (cambios.saldo) {
    frases.push('El saldo con ' + r.acreedor + ' pasó de \u20B2 ' + plata(cambios.saldo.antes) +
      ' a \u20B2 ' + plata(cambios.saldo.despues) + '.');
  } else if (cambios.cuota) {
    frases.push('La cuota de ' + r.acreedor + ' quedó en \u20B2 ' + plata(cambios.cuota.despues) + '.');
  } else {
    frases.push('Actualicé la deuda con ' + r.acreedor + '.');
  }

  if (r.cuota) {
    frases.push('Cuota de \u20B2 ' + plata(r.cuota) + (r.cuota_dia ? ' el ' + r.cuota_dia + ' de cada mes' : '') + '.');
  }

  /*
    Tres finales posibles, y cada uno manda a un lado distinto.

    Decir "la ves en Personal con el orden en que conviene pagar" cuando esa
    tarjeta no se va a mostrar —porque falta la Constitución Financiera, que es
    de donde sale la capacidad de pago— es prometer una pantalla vacía.
  */
  if (r.sin_cuota) {
    frases.push('Todavía no sé de cuánto es la cuota: sin eso no puedo meterla en el plan de pago del mes.');
  } else if (r.plan_listo === false) {
    frases.push('Para armarte el plan de pago me falta saber cuánto cobrás y cuánto se te va por mes. Contámelo y calculo en qué orden conviene pagar.');
  } else {
    frases.push('La ves en Personal, con el orden en que conviene pagar.');
  }

  return frases.join(' ');
}

/*
  El pago escribe en dos tablas y la frase dice las dos: la deuda bajó y la
  plata salió. Si solo dijera una, la otra sería una sorpresa — un gasto que
  nadie recuerda, o una deuda que no baja nunca.
*/
function fraseDePagoDeuda(result) {
  const r = (result && result.resultado) || {};
  if (!r.acreedor) return 'No quedó registrado el pago.';

  const frases = [];

  frases.push('Pagaste \u20B2 ' + plata(r.pagado) + ' a ' + r.acreedor + '.');

  if (r.saldada) {
    frases.push('Con eso la saldaste: ya no te queda nada con ' + r.acreedor + '.');
  } else {
    frases.push('Te queda \u20B2 ' + plata(r.saldo_despues) + ', de \u20B2 ' + plata(r.saldo_antes) + '.');
    if (r.cuotas_totales) {
      frases.push('Vas ' + r.cuotas_pagadas + ' de ' + r.cuotas_totales + ' cuotas.');
    }
  }

  frases.push('Lo conté también como gasto de este mes en Personal.');

  return frases.join(' ');
}

/*
  Dice explícitamente que NO es un gasto.

  Es la única confirmación del sistema que tiene que negar algo, y hace falta:
  la persona acaba de ver a EOS anotar sus gastos toda la semana, y sin esa
  frase queda con la duda de si esta transferencia le va a aparecer como uno.
  Esa duda es la que hace que la gente deje de anotarlas.
*/
function fraseDeTransferencia(result) {
  const r = (result && result.resultado) || {};
  if (!r.monto) return 'No quedó registrada la transferencia.';

  const cierre = (r.origen_conocida && r.destino_conocida)
    ? ''
    : ' Todavía no tengo esas cuentas cargadas: si las agregás en Personal, puedo seguirte el saldo de cada una.';

  return 'Moviste ₲ ' + plata(r.monto) + ' de ' + r.origen + ' a ' + r.destino +
    '. No lo cuento como gasto ni como ingreso: la plata es la misma, cambió de lugar.' + cierre;
}

/*
  La frase de CREAR_PRODUCTO se arma con lo que pasó, no con un texto fijo.

  El ejecutor devuelve `creados` y `ya_existian` (v132). Sin mirarlos, la
  respuesta decía "los productos quedaron cargados" incluso cuando no se cargó
  ninguno porque todos ya estaban — y quien lo lee se va creyendo que le
  cambiamos el precio.
*/
function fraseDeProductos(result) {
  const r = (result && result.resultado) || {};
  const creados = Array.isArray(r.creados) ? r.creados : [];
  const existian = Array.isArray(r.ya_existian) ? r.ya_existian : [];

  const partes = [];

  if (creados.length === 1) {
    partes.push(`Cargué \u201C${creados[0].nombre}\u201D en tu catálogo.`);
  } else if (creados.length > 1) {
    partes.push(`Cargué ${creados.length} productos en tu catálogo.`);
  }

  if (existian.length === 1) {
    partes.push(
      `\u201C${existian[0]}\u201D ya estaba y no le toqué el precio: cambiarlo todavía se hace desde Negocio > Productos.`
    );
  } else if (existian.length > 1) {
    partes.push(
      `${existian.length} ya estaban y no les toqué el precio: cambiarlo todavía se hace desde Negocio > Productos.`
    );
  }

  if (!partes.length) return 'No quedó ningún producto para cargar.';

  if (creados.length) partes.push('Los ves en Negocio > Productos.');

  return partes.join(' ');
}

/*
  El motivo de verdad, y siempre como texto.

  Cuando el efecto interno falla, `result` es el objeto de error de Axios y
  `result.error` es `{ message, name, stack }`. Poner eso en `respuesta`
  mandaba un rastro de pila con rutas del servidor al chat de la persona.

  Y el cuerpo de la respuesta viene con DOS niveles de escape adentro del
  mensaje de Axios:

      422 - "{\"ok\":false,\"error\":\"No encontré a \\\"Rossana\\\"…\"}"

  Desde la primera comilla, eso es un literal JSON completo: parsearlo una vez
  da el texto del cuerpo, parsearlo otra vez da el objeto. Sin expresiones
  regulares y sin reescribir comillas a mano, que es donde falló el primer
  intento.
*/
function motivoDelError(result) {
  const directo = result && result.error;
  if (typeof directo === 'string' && directo.trim()) return directo.trim();

  const crudo =
    (directo && typeof directo === 'object' && typeof directo.message === 'string' && directo.message) ||
    (result && typeof result.message === 'string' && result.message) ||
    '';

  const comilla = crudo.indexOf('"');

  if (comilla >= 0) {
    try {
      const cuerpo = JSON.parse(JSON.parse(crudo.slice(comilla)));
      if (cuerpo && typeof cuerpo.error === 'string' && cuerpo.error.trim()) {
        return cuerpo.error.trim();
      }
    } catch (e) { /* sigue abajo */ }
  }

  // Por si algún día el cuerpo llega sin envolver en un literal de texto.
  const llave = crudo.indexOf('{');
  if (llave >= 0) {
    try {
      const cuerpo = JSON.parse(crudo.slice(llave));
      if (cuerpo && typeof cuerpo.error === 'string' && cuerpo.error.trim()) {
        return cuerpo.error.trim();
      }
    } catch (e) { /* se cae al genérico */ }
  }

  return 'No fue posible completar la acción interna.';
}
